 * NotificationForm — React-style component rendered into #app.
 *
 * Accessibility contract:
 *  - Validates on submit; focuses first invalid control on failure.
 *  - Error is announced via aria-live (the error element) and
 *    aria-invalid on the fieldset (supported as an ARIA state hint).
 *  - Success confirmation is in an aria-live="polite" region.
 */

const NOTIFICATION_OPTIONS = [
  { value: "email",  label: "Email",              icon: "✉️" },
  { value: "sms",    label: "SMS",                icon: "💬" },
  { value: "push",   label: "Push Notifications", icon: "🔔" },
];

// ── Utility: create element with attributes and children ──────
function h(tag, attrs = {}, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "textContent") { el.textContent = v; }
    else if (k === "innerHTML") { el.innerHTML = v; }
    else { el.setAttribute(k, v); }
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    el.append(typeof child === "string" ? document.createTextNode(child) : child);
  }
  return el;
}

// ── RadioOption component ─────────────────────────────────────
function RadioOption({ value, label, icon, groupName }) {
  const id = `notif-${value}`;

  const input = h("input", {
    type: "radio",
    id,
    name: groupName,
    value,
    required: "",
  });

  const labelEl = h("label", { for: id }, label);

  const iconEl = h("span", { "aria-hidden": "true", class: "option-icon" }, icon);

  const wrapper = h("div", { class: "radio-option" }, iconEl, input, labelEl);

  // Clicking anywhere on the card activates the radio
  wrapper.addEventListener("click", (e) => {
    if (e.target !== input) input.click();
  });

  return wrapper;
}

// ── NotificationForm component ────────────────────────────────
function NotificationForm() {
  const GROUP_NAME   = "notification-preference";
