const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const html = fs.readFileSync('index.html', 'utf8');
  await page.setContent(html, { waitUntil: 'load' });
  // inject app.js and styles via inline since we use relative paths
  const css = fs.readFileSync('styles.css', 'utf8');
  const js  = fs.readFileSync('app.js', 'utf8');
  await page.addStyleTag({ content: css });
  await page.addScriptTag({ content: js });
  await page.waitForTimeout(300);
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate('async () => await window.axe.run()');
  await browser.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
  const fmt  = v => ({ id: v.id, impact: v.impact, tags: v.tags.filter(t=>t.startsWith('wcag')), targets: v.nodes.map(n=>n.target), help: v.help });
  process.stdout.write(JSON.stringify({ wcag: wcag.map(fmt), bp: bp.map(fmt) }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
