  '#4b5563':           [75, 85, 99],
  '#595f6e':           [89, 95,110],
  '#5c6370':           [92, 99,112],
};
for (const [name, rgb] of Object.entries(candidates)) {
  const c = contrast(bg, lum(rgb));
  console.log(name, '->', c.toFixed(2) + ':1', c >= 4.5 ? '✓' : '✗ FAIL');
}
"
