  width: 1.125rem;
  height: 1.125rem;
  min-width: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-surface);
  cursor: pointer;
  position: relative;
  transition: border-color var(--transition-quick),
              background var(--transition-quick);
}

.radio-option input[type="radio"]:checked {
  border-color: var(--color-radio-check);
  background: var(--color-radio-check);
}

.radio-option input[type="radio"]:checked::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: #fff;
}

/* Visible focus ring that satisfies 3:1 contrast */
.radio-option input[type="radio"]:focus-visible {
