const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(fs.readFileSync('index.html', 'utf8'), { waitUntil: 'load' });
  await page.addStyleTag({ content: fs.readFileSync('styles.css', 'utf8') });
  await page.addScriptTag({ content: fs.readFileSync('app.js', 'utf8') });
  await page.waitForTimeout(300);
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  await page.waitForTimeout(200);

  const result = await page.evaluate(() => {
    return window.axe.run(document).then(r => JSON.stringify({
      violations: r.violations.map(v => ({
        id: v.id, impact: v.impact,
        tags: v.tags.filter(t => t.startsWith('wcag')),
        targets: v.nodes.map(n => n.target),
        help: v.help
      }))
    })).catch(e => JSON.stringify({ error: e.message }));
  });
  await browser.close();
  const parsed = JSON.parse(result);
  const wcag = parsed.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = parsed.violations.filter(v =>  v.tags.includes('best-practice'));
  console.log(JSON.stringify({ wcag, bp, total_violations: parsed.violations.length }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch(e => { console.error('FATAL:', e.message); process.exit(2); });
