 // ── RadioOption component ─────────────────────────────────────
 function RadioOption({ value, label, icon, groupName }) {
   const id = `notif-${value}`;

   const input = h("input", {
     type: "radio",
     id,
     name: groupName,
     value,
     required: "",
   });

   const labelEl = h("label", { for: id }, label);

   const iconEl = h("span", { "aria-hidden": "true", class: "option-icon" }, icon);

   const wrapper = h("div", { class: "radio-option" }, iconEl, input, labelEl);

