 // ── NotificationForm component ────────────────────────────────
 function NotificationForm() {
   const GROUP_NAME   = "notification-preference";
   const FIELDSET_ID  = "notif-group";
   const ERROR_ID     = "notif-error";
   const STATUS_ID    = "form-status";

   // Error element
   const errorEl = h("p", {
     id: ERROR_ID,
     class: "field-error",
     role: "alert",
     "aria-live": "assertive",
   });
   // Inner content set dynamically; keep element in DOM for aria-describedby

