/* ── Skip link ─────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius-control) var(--radius-control);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition-quick);
}
.skip-link:focus { top: 0; }

/* ── Page header ───────────────────────────────────────────── */
.page-header {
  width: 100%;
  max-width: 560px;
  margin-bottom: 1.5rem;
  text-align: center;
}

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.page-header p {
  margin-top: 0.375rem;
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ── Card ──────────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 2rem;
  width: 100%;
  max-width: 560px;
}

/* ── Form ──────────────────────────────────────────────────── */
.notification-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* ── Required note ─────────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 0.25rem;
}

.required-note abbr {
  text-decoration: none;
  color: var(--color-error);
  font-weight: 600;
}

/* ── Form field wrapper ────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

/* ── Fieldset / legend ─────────────────────────────────────── */
.form-field fieldset {
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-control);
  padding: 1.25rem 1.25rem 1rem;
  transition: border-color var(--transition-quick);
}

.form-field fieldset:focus-within {
  border-color: var(--color-border-focus);
}

.form-field fieldset legend {
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-text);
  padding: 0 0.25rem;
  line-height: 1.4;
}

.required-star {
  color: var(--color-error);
  font-weight: 700;
  margin-left: 0.15em;
}

/* ── Radio options list ────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  margin-top: 0.75rem;
}

/* ── Individual radio option ───────────────────────────────── */
.radio-option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-control);
  cursor: pointer;
  transition: border-color var(--transition-quick),
              background var(--transition-quick);
  user-select: none;
}

.radio-option:hover {
  border-color: var(--color-primary);
  background: #f5f3ff;
}

.radio-option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  min-width: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-surface);
  cursor: pointer;
  position: relative;
  transition: border-color var(--transition-quick),
              background var(--transition-quick);
}

.radio-option input[type="radio"]:checked {
  border-color: var(--color-radio-check);
  background: var(--color-radio-check);
}

.radio-option input[type="radio"]:checked::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: #fff;
}

/* Visible focus ring — satisfies 3:1 contrast */
.radio-option input[type="radio"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.radio-option:has(input[type="radio"]:checked) {
  border-color: var(--color-primary);
  background: #f5f3ff;
}

.radio-option label {
  font-size: 0.9375rem;
  cursor: pointer;
  flex: 1;
  color: var(--color-text);
}

/* ── Option icon ───────────────────────────────────────────── */
.option-icon {
  font-size: 1.125rem;
  line-height: 1;
  flex-shrink: 0;
}

/* ── Error state ───────────────────────────────────────────── */
.form-field fieldset[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

.form-field fieldset[aria-invalid="true"] legend {
  color: var(--color-error);
}

.field-error {
  display: none;
  font-size: 0.875rem;
  color: var(--color-error);
  font-weight: 500;
  padding: 0.375rem 0.5rem;
  border-radius: 4px;
  align-items: center;
  gap: 0.375rem;
}

.field-error.visible {
  display: flex;
}

/* ── Submit button ─────────────────────────────────────────── */
.submit-btn {
  appearance: none;
  background: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-control);
  padding: 0.8125rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background var(--transition-quick),
              box-shadow var(--transition-quick),
              transform var(--transition-quick);
  width: 100%;
  letter-spacing: 0.01em;
}

.submit-btn:hover {
  background: var(--color-primary-dark);
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.35);
}

.submit-btn:active { transform: translateY(1px); }

.submit-btn:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ── Status message (live region) ──────────────────────────── */
.status-message {
  display: none;
  align-items: center;
  gap: 0.625rem;
  padding: 0.875rem 1rem;
  border-radius: var(--radius-control);
  font-size: 0.9375rem;
  font-weight: 500;
}

.status-message.success {
  display: flex;
  background: var(--color-success-bg);
  color: var(--color-success);
  border: 1.5px solid #86efac;
