  const legend = h("legend", {},
    "How do you prefer to receive notifications?",
    h("span", { class: "required-star", "aria-hidden": "true" }, " *"),
  );

  const optionsContainer = h("div", { class: "radio-options" },
    ...NOTIFICATION_OPTIONS.map((opt) =>
      RadioOption({ ...opt, groupName: GROUP_NAME })
    ),
  );

  const fieldset = h("fieldset", {
    "aria-describedby": ERROR_ID,
  }, legend, optionsContainer);

  // .form-field wrapper (required by spec)
  const formField = h("div", { class: "form-field" }, fieldset, errorEl);

  // Status live region
  const statusEl = h("div", {
    id: STATUS_ID,
    class: "status-message",
    role: "status",
    "aria-live": "polite",
    "aria-atomic": "true",
  });

  // Submit button
  const submitBtn = h("button", { type: "submit", class: "submit-btn" },
    "Save preferences"
  );

  // ── Validation helpers ──────────────────────────────────────
  function showError(msg) {
    errorEl.textContent = `Error: ${msg}`;
    errorEl.classList.add("visible");
    fieldset.setAttribute("aria-invalid", "true");
  }

  function clearError() {
    errorEl.textContent = "";
    errorEl.classList.remove("visible");
    fieldset.removeAttribute("aria-invalid");
  }

