    if (!selected) {
      showError("Please select a notification preference.");
      // Focus first radio so keyboard users can act immediately
      const firstRadio = form.querySelector(`input[name="${GROUP_NAME}"]`);
      firstRadio?.focus();
      return;
    }

    const chosenLabel = NOTIFICATION_OPTIONS.find(
      (o) => o.value === selected.value
    )?.label ?? selected.value;

    showSuccess(`✓ Preferences saved! You'll receive notifications via ${chosenLabel}.`);
  });

  // Clear error as soon as any radio is selected
  form.addEventListener("change", (e) => {
    if (e.target.name === GROUP_NAME) clearError();
  });

  return form;
}

